#pragma once
#include "Examples.h"
inline void Examples::line_squisher(){{freopen("output.txt","w",stdout);std::string k;std::getline(std::cin,k);while(k!="END"){{std::string str;if(k==""){{std::getline(std::cin,k);continue;}}if(k[0]=='#'){{std::cout<<k<<std::endl;std::getline(std::cin,k);continue;}}bool t=true;if(k[0]!=' '&&k[0]!='/')str+=k[0];int cnt=0;for(int i=1;i<k.size()-1;i++){{if(k[i-1]=='/'&&k[i]=='/'){{std::cout<<str.substr(0,str.size()-1);std::getline(std::cin,k);t=false;break;}}if(k[i]=='\''||k[i] =='\"')cnt++;if(k[i]==' '){{if(!(isalpha(k[i-1])||isdigit(k[i-1]))||!(isalpha(k[i+1])||isdigit(k[i+1]))){{if((k[i-1]!='>'||k[i+1]!='>')&&cnt%2==0)continue;}}}}str+=k[i];}}if(!t)continue;if(k[k.size()-1]!=' ')str+=k[k.size()-1];std::cout<<str;std::getline(std::cin,k);}}}}